import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.Dkh1x705.js";var i=JSON.parse(`{"title":"Вопросы и типичные ошибки","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":0}`),a={name:`guide/faq.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="вопросы-и-типичные-ошибки" tabindex="-1">Вопросы и типичные ошибки <a class="header-anchor" href="#вопросы-и-типичные-ошибки" aria-label="Permalink to “Вопросы и типичные ошибки”">​</a></h1><p>Ответы на частые вопросы и разбор сообщений, которые показывает расширение. Каждый пункт — со ссылкой, чтобы отправить коллеге конкретное решение.</p><h2 id="расширение-не-работает" tabindex="-1">Расширение не работает <a class="header-anchor" href="#расширение-не-работает" aria-label="Permalink to “Расширение не работает”">​</a></h2><h3 id="no-buttons" tabindex="-1">Кнопки не появились на карте <a class="header-anchor" href="#no-buttons" aria-label="Permalink to “Кнопки не появились на карте”">​</a></h3><ol><li>Убедитесь, что открыт именно редактор: <code>n.maps.yandex.ru</code>. На <code>yandex.ru/maps</code> расширение не работает.</li><li>Обновите вкладку: content scripts подключаются при загрузке страницы.</li><li>Проверьте, что расширение включено в браузере и не отключено после обновления (Chrome иногда просит подтвердить разрешения).</li><li>Если кнопок нет только у одного объекта — часть действий живёт в меню «Ещё» карточки объекта.</li></ol><h3 id="extension-disappeared" tabindex="-1">Расширение «исчезло» после перезапуска браузера <a class="header-anchor" href="#extension-disappeared" aria-label="Permalink to “Расширение «исчезло» после перезапуска браузера”">​</a></h3><p>Проверьте список расширений: в Chrome и Яндекс.Браузере после обновления расширение может требовать повторного включения. В Firefox — страница <code>about:addons</code>. Если расширение включено, но кнопок нет, обновите вкладку карты.</p><h2 id="авторизация-и-доступ-к-диску" tabindex="-1">Авторизация и доступ к Диску <a class="header-anchor" href="#авторизация-и-доступ-к-диску" aria-label="Permalink to “Авторизация и доступ к Диску”">​</a></h2><h3 id="auth-required" tabindex="-1">«Необходима авторизация. Войдите через Яндекс ID» <a class="header-anchor" href="#auth-required" aria-label="Permalink to “«Необходима авторизация. Войдите через Яндекс ID»”">​</a></h3><p>Расширению нужен доступ к Яндекс Диску, чтобы прочитать и записать <code>index.json</code>.</p><ol><li>Нажмите «Войти» в окне загрузки или в панели.</li><li>Разрешите доступ к Диску в окне Яндекс ID.</li><li>Повторите загрузку.</li></ol><p>Пока доступа нет, кнопки, которым нужен Диск, показывают «Разрешить доступ».</p><h3 id="session-expired" tabindex="-1">«Сессия истекла. Повторите загрузку для повторного входа» <a class="header-anchor" href="#session-expired" aria-label="Permalink to “«Сессия истекла. Повторите загрузку для повторного входа»”">​</a></h3><p>Токен доступа устарел или был отозван. Повторите загрузку — расширение заново откроет окно входа. Если это повторяется, выйдите из аккаунта в панели и войдите снова.</p><h3 id="access-denied" tabindex="-1">«Доступ запрещён» при чтении папок <a class="header-anchor" href="#access-denied" aria-label="Permalink to “«Доступ запрещён» при чтении папок”">​</a></h3><p>Проверьте, что доступ к Диску выдан именно приложению расширения, а не только аккаунту в браузере. Отозвать и выдать заново можно в <a href="https://id.yandex.ru/" target="_blank" rel="noreferrer">настройках Яндекс ID</a>.</p><h2 id="загрузка-данных" tabindex="-1">Загрузка данных <a class="header-anchor" href="#загрузка-данных" aria-label="Permalink to “Загрузка данных”">​</a></h2><h3 id="uploaded-not-visible" tabindex="-1">Файл загрузился, но в блокноте его нет <a class="header-anchor" href="#uploaded-not-visible" aria-label="Permalink to “Файл загрузился, но в блокноте его нет”">​</a></h3><p>Причины по частоте:</p><ol><li><strong>Не та дата.</strong> Данные записаны в запись за дату из поля «Дата блокнота», а редактор показывает свою дату. Сверьте даты.</li><li><strong>Редактор не обновил данные.</strong> Включите <a href="/yamapper/guide/editor/#reload-after-upload">автообновление после загрузки</a> или обновите страницу карты.</li><li><strong>Не тот аккаунт.</strong> Блокнот читает тот Яндекс Диск, под которым вы вошли в редакторе. Если расширение авторизовано другим аккаунтом, данные уйдут на другой Диск.</li></ol><h3 id="unsupported-format" tabindex="-1">«Неподдерживаемый формат» <a class="header-anchor" href="#unsupported-format" aria-label="Permalink to “«Неподдерживаемый формат»”">​</a></h3><p>Поддерживаются <code>.zip</code>, <code>.geojson</code>, <code>.gpx</code>, <code>.kml</code>, <code>.kmz</code>, <code>.topojson</code>, <code>.wkt</code>. Для Shapefile нужен <code>.zip</code> с набором файлов; одиночный <code>.shp</code> не подойдёт. Подробнее — в разделе <a href="/yamapper/guide/formats">«Форматы»</a>.</p><h3 id="shapefile-encoding" tabindex="-1">Shapefile загрузился без названий или с «кракозябрами» <a class="header-anchor" href="#shapefile-encoding" aria-label="Permalink to “Shapefile загрузился без названий или с «кракозябрами»”">​</a></h3><p>Атрибуты в <code>.dbf</code> записаны в кодировке, которую расширение не распознало. Переэкспортируйте слой в UTF-8 (в QGIS: «Кодировка» при экспорте) и загрузите архив заново.</p><h3 id="wrong-position" tabindex="-1">Объект не на своём месте <a class="header-anchor" href="#wrong-position" aria-label="Permalink to “Объект не на своём месте”">​</a></h3><p>Расширение не перепроецирует координаты: они читаются как долгота и широта (WGS84, EPSG:4326). Если исходные данные в другой проекции, переэкспортируйте их в WGS84 перед загрузкой.</p><h3 id="invalid-date" tabindex="-1">«Неверный формат даты» <a class="header-anchor" href="#invalid-date" aria-label="Permalink to “«Неверный формат даты»”">​</a></h3><p>Дата вводится как <code>дд-мм-гггг</code>. Проверьте разделители и что день и месяц не перепутаны.</p><h2 id="нспд" tabindex="-1">НСПД <a class="header-anchor" href="#нспд" aria-label="Permalink to “НСПД”">​</a></h2><h3 id="nspd-no-button" tabindex="-1">Не появляется кнопка «Загрузка из НСПД» <a class="header-anchor" href="#nspd-no-button" aria-label="Permalink to “Не появляется кнопка «Загрузка из НСПД»”">​</a></h3><ol><li>Включите тумблер в настройках: Настройки → Редактор → «Загрузка из НСПД».</li><li>Если доступа к <code>nspd.gov.ru</code> нет, в строке настройки появится кнопка «Разрешить доступ» — нажмите её.</li><li>Обновите вкладку карты после выдачи разрешения.</li></ol><h3 id="nspd-upload-fails" tabindex="-1">НСПД открылся, но объект не выгружается <a class="header-anchor" href="#nspd-upload-fails" aria-label="Permalink to “НСПД открылся, но объект не выгружается”">​</a></h3><p>Для записи в Блокнот нужен доступ к Яндекс Диску — он запрашивается отдельно от доступа к НСПД. Разрешите его и повторите выгрузку. Если объект не выбран на карте НСПД, кнопка выгрузки не сработает.</p><h2 id="заметки" tabindex="-1">Заметки <a class="header-anchor" href="#заметки" aria-label="Permalink to “Заметки”">​</a></h2><h3 id="notes-permission" tabindex="-1">Панель заметок пуста или пишет «Требуется разрешение» <a class="header-anchor" href="#notes-permission" aria-label="Permalink to “Панель заметок пуста или пишет «Требуется разрешение»”">​</a></h3><p>Заметки хранятся на Яндекс Диске в <code>Приложения/Nmap Uploader</code>. Нажмите «Разрешить доступ» в панели: после ответа браузера вход выполнится автоматически. Если доступ уже выдан, но список пуст — проверьте, что вы вошли в тот аккаунт, где лежат заметки.</p><h3 id="notes-load-error" tabindex="-1">«Не удалось загрузить заметки» <a class="header-anchor" href="#notes-load-error" aria-label="Permalink to “«Не удалось загрузить заметки»”">​</a></h3><p>Обычно это сеть или истёкший токен. Нажмите «Повторить»; если не помогает — обновите страницу и войдите заново. Заметки при этом не теряются: они лежат файлами на Диске.</p><h3 id="notes-save-error" tabindex="-1">«Не удалось сохранить» заметку <a class="header-anchor" href="#notes-save-error" aria-label="Permalink to “«Не удалось сохранить» заметку”">​</a></h3><p>Проверьте доступ к Диску и свободное место. Если ошибка повторяется на одной заметке — сохраните её текст в описание другой заметки и приложите шаги в Issues.</p><h2 id="лимиты-редактора" tabindex="-1">Лимиты редактора <a class="header-anchor" href="#лимиты-редактора" aria-label="Permalink to “Лимиты редактора”">​</a></h2><h3 id="point-limit" tabindex="-1">«Достигнут лимит на количество вершин» <a class="header-anchor" href="#point-limit" aria-label="Permalink to “«Достигнут лимит на количество вершин»”">​</a></h3><p>У объекта блокнота лимит 500 вершин. Включите <a href="/yamapper/guide/editor/#point-counter">счётчик вершин</a>, чтобы видеть остаток, и упростите контур: уберите лишние точки или разбейте объект на части.</p><h3 id="object-limit" tabindex="-1">«Достигнут лимит наблюдения: не больше 30 объектов» <a class="header-anchor" href="#object-limit" aria-label="Permalink to “«Достигнут лимит наблюдения: не больше 30 объектов»”">​</a></h3><p>Снимите с наблюдения объекты, которые больше не нужны: меню «Ещё» карточки объекта → «Не наблюдать», либо удалите их во вкладке «Мои объекты».</p><h2 id="раздельныи-вид" tabindex="-1">Раздельный вид <a class="header-anchor" href="#раздельныи-вид" aria-label="Permalink to “Раздельный вид”">​</a></h2><h3 id="split-view-blank" tabindex="-1">Правая часть пустая или Nakarte не загрузился <a class="header-anchor" href="#split-view-blank" aria-label="Permalink to “Правая часть пустая или Nakarte не загрузился”">​</a></h3><p>Проверьте доступ к <code>nakarte.me</code> (расширение запрашивает его при установке) и сеть. Если часть белая после долгой работы — закройте и снова откройте режим кнопкой раздельного вида.</p><h3 id="split-view-zoom" tabindex="-1">Раздельный вид «съехал» по масштабу <a class="header-anchor" href="#split-view-zoom" aria-label="Permalink to “Раздельный вид «съехал» по масштабу”">​</a></h3><p>Режим синхронизирует центр и зум, но не ограничивает максимальный зум Nakarte. Если одна половина ушла дальше другой, подгоните масштаб вручную — при следующем движении синхронизация восстановится.</p><h2 id="стиль" tabindex="-1">Стиль <a class="header-anchor" href="#стиль" aria-label="Permalink to “Стиль”">​</a></h2><h3 id="stroke-color-error" tabindex="-1">Цвет обводки не применяется <a class="header-anchor" href="#stroke-color-error" aria-label="Permalink to “Цвет обводки не применяется”">​</a></h3><p>Сообщение «Не удалось применить цвет» значит, что вкладка карты открыта до установки или обновления расширения. Обновите страницу редактора.</p><h2 id="диагностика-и-логи" tabindex="-1">Диагностика и логи <a class="header-anchor" href="#диагностика-и-логи" aria-label="Permalink to “Диагностика и логи”">​</a></h2><p>Если ошибка не описана выше:</p><ol><li>Откройте консоль браузера на <code>n.maps.yandex.ru</code> (<code>F12</code> → Console) и найдите сообщения с префиксом <code>[nmap</code> — по ним видно, какой модуль упал.</li><li>Соберите версию расширения (настройки → номер версии), версию браузера и шаги воспроизведения.</li><li>Приложите всё в <a href="https://github.com/vibecodinguser/yamapper/issues" target="_blank" rel="noreferrer">Issues</a>.</li></ol><p>Что ещё стоит приложить — в разделе <a href="/yamapper/guide/support">«Поддержка»</a>.</p>`,57)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};